char * glewlwyd_metrics_build_label(va_list vl_label) { /* <=== glewlwyd_metrics_build_label */ 
  const char * label_arg;
  char * label = NULL;
  int flag = 0;

  for (label_arg = va_arg(vl_label, const char *); label_arg != NULL; label_arg = va_arg(vl_label, const char *)) {
    if (!flag) {
      if (label == NULL) {
        label = msprintf("%s=", label_arg);
      } else {
        label = mstrcatf(label, ", %s=", label_arg);
      }
    } else {
      label = mstrcatf(label, "\"%s\"", label_arg);
    }
    flag = !flag;
  }
  return label;
}

json_t * get_session_for_username(struct config_elements * config, const char * session_uid, const char * username) { /* <=== get_session_for_username */ 
  json_t * j_query, * j_result, * j_return, * j_session_scheme;
  int res;
  char * expire_clause;
  char * session_uid_hash = generate_hash(config->hash_algorithm, session_uid);

  if (config->conn->type==HOEL_DB_TYPE_MARIADB) {
    expire_clause = o_strdup("> NOW()");
  } else if (config->conn->type==HOEL_DB_TYPE_PGSQL) {
    expire_clause = o_strdup("> NOW()");
  } else { // HOEL_DB_TYPE_SQLITE
    expire_clause = o_strdup("> (strftime('%s','now'))");
  }
  if (session_uid_hash != NULL) {
    j_query = json_pack("{sss[ss]s{sssssis{ssss}}}",
                        "table",
                        GLEWLWYD_TABLE_USER_SESSION,
                        "columns",
                          "gus_id",
                          SWITCH_DB_TYPE(config->conn->type, "UNIX_TIMESTAMP(gus_expiration) AS expiration", "gus_expiration AS expiration", "EXTRACT(EPOCH FROM gus_expiration)::integer AS expiration"),
                        "where",
                          "gus_session_hash",
                          session_uid_hash,
                          "gus_username",
                          username,
                          "gus_enabled",
                          1,
                          "gus_expiration",
                            "operator",
                            "raw",
                            "value",
                            expire_clause);
    o_free(expire_clause);
    res = h_select(config->conn, j_query, &j_result, NULL);
    json_decref(j_query);
    if (res == H_OK) {
      if (json_array_size(j_result) > 0) {
        j_session_scheme = get_session_scheme(config, json_integer_value(json_object_get(json_array_get(j_result, 0), "gus_id")));
        if (check_result_value(j_session_scheme, G_OK)) {
          j_return = json_pack("{sis{sssOsOsI}}", 
                                "result", 
                                G_OK, 
                                "session", 
                                  "username", 
                                  username, 
                                  "expiration", 
                                  json_object_get(json_array_get(j_result, 0), "expiration"),
                                  "scheme",
                                  json_object_get(j_session_scheme, "scheme"),
                                  "gus_id",
                                  json_integer_value(json_object_get(json_array_get(j_result, 0), "gus_id")));
        } else {
          y_log_message(Y_LOG_LEVEL_ERROR, "get_session_for_username - Error get_session_scheme");
          j_return = json_pack("{si}", "result", G_ERROR);
        }
        json_decref(j_session_scheme);
      } else {
        j_return = json_pack("{si}", "result", G_ERROR_NOT_FOUND);
      }
      json_decref(j_result);
    } else {
      y_log_message(Y_LOG_LEVEL_ERROR, "get_session_for_username - Error executing j_query");
      glewlwyd_metrics_increment_counter_va(config, GLWD_METRICS_DATABSE_ERROR, 1, NULL);
      j_return = json_pack("{si}", "result", G_ERROR_DB);
    }
    o_free(session_uid_hash);
  } else {
    y_log_message(Y_LOG_LEVEL_ERROR, "get_session_for_username - Error generate_hash");
    j_return = json_pack("{si}", "result", G_ERROR);
  }
  return j_return;
}

int glewlwyd_metrics_increment_counter_va(struct config_elements * config, const char * name, size_t inc, ...) { /* <=== glewlwyd_metrics_increment_counter_va */ 
  va_list vl;
  char * label = NULL;
  int ret = G_OK;

  if (config->metrics_endpoint) {
    if (config != NULL && o_strlen(name)) {
      va_start(vl, inc);
      label = glewlwyd_metrics_build_label(vl);
      va_end(vl);

      ret = glewlwyd_metrics_increment_counter(config, name, label, inc);
      o_free(label);
    } else {
      y_log_message(Y_LOG_LEVEL_ERROR, "glewlwyd_metrics_increment_counter_va - Error input values");
      ret = G_ERROR_PARAM;
    }
  }
  return ret;
}

json_t * get_user_module_list(struct config_elements * config) { /* <=== get_user_module_list */ 
  int res;
  json_t * j_query, * j_result = NULL, * j_return, * j_parameters, * j_element;
  size_t index;

  j_query = json_pack("{sss[ssssssss]ss}",
                      "table",
                      GLEWLWYD_TABLE_USER_MODULE_INSTANCE,
                      "columns",
                        "gumi_module AS module",
                        "gumi_name AS name",
                        "gumi_display_name AS display_name",
                        "gumi_parameters",
                        "gumi_order AS order_rank",
                        "gumi_readonly",
                        "gumi_multiple_passwords",
                        "gumi_enabled",
                      "order_by",
                      "gumi_order");
  res = h_select(config->conn, j_query, &j_result, NULL);
  json_decref(j_query);
  if (res == H_OK) {
    json_array_foreach(j_result, index, j_element) {
      j_parameters = json_loads(json_string_value(json_object_get(j_element, "gumi_parameters")), JSON_DECODE_ANY, NULL);
      if (j_parameters != NULL) {
        json_object_set_new(j_element, "parameters", j_parameters);
      } else {
        y_log_message(Y_LOG_LEVEL_ERROR, "get_user_module_list - Error parsing parameters for module %s %s", json_string_value(json_object_get(j_element, "name")), json_string_value(json_object_get(j_element, "gumi_parameters")));
        json_object_set_new(j_element, "parameters", json_null());
      }
      json_object_del(j_element, "gumi_parameters");

      json_object_set_new(j_element, "enabled", json_integer_value(json_object_get(j_element, "gumi_enabled"))?json_true():json_false());
      json_object_del(j_element, "gumi_enabled");

      json_object_set_new(j_element, "readonly", json_integer_value(json_object_get(j_element, "gumi_readonly"))?json_true():json_false());
      json_object_del(j_element, "gumi_readonly");

      json_object_set_new(j_element, "multiple_passwords", json_integer_value(json_object_get(j_element, "gumi_multiple_passwords"))?json_true():json_false());
      json_object_del(j_element, "gumi_multiple_passwords");
    }
    j_return = json_pack("{sisO}", "result", G_OK, "module", j_result);
  } else {
    y_log_message(Y_LOG_LEVEL_ERROR, "get_user_module_list - Error executing j_query");
    glewlwyd_metrics_increment_counter_va(config, GLWD_METRICS_DATABSE_ERROR, 1, NULL);
    j_return = json_pack("{si}", "result", G_ERROR_DB);
  }
  json_decref(j_result);
  return j_return;
}

struct _user_module_instance * get_user_module_instance(struct config_elements * config, const char * name) { /* <=== get_user_module_instance */ 
  size_t i;
  struct _user_module_instance * cur_instance;

  for (i=0; i<pointer_list_size(config->user_module_instance_list); i++) {
    cur_instance = (struct _user_module_instance *)pointer_list_get_at(config->user_module_instance_list, i);
    if (cur_instance != NULL && 0 == o_strcmp(cur_instance->name, name)) {
      return cur_instance;
    }
  }
  return NULL;
}

json_t * auth_check_user_credentials(struct config_elements * config, const char * username, const char * password) { /* <=== auth_check_user_credentials */ 
  int res;
  json_t * j_return = NULL, * j_module_list = get_user_module_list(config), * j_module, * j_user;
  struct _user_module_instance * user_module;
  size_t index;

  if (check_result_value(j_module_list, G_OK)) {
    json_array_foreach(json_object_get(j_module_list, "module"), index, j_module) {
      if (j_return == NULL) {
        user_module = get_user_module_instance(config, json_string_value(json_object_get(j_module, "name")));
        if (user_module != NULL) {
          if (user_module->enabled) {
            j_user = user_module->module->user_module_get(config->config_m, username, user_module->cls);
            if (check_result_value(j_user, G_OK) && json_object_get(json_object_get(j_user, "user"), "enabled") == json_true()) {
              res = user_module->module->user_module_check_password(config->config_m, username, password, user_module->cls);
              if (res == G_OK) {
                j_return = json_pack("{si}", "result", G_OK);
              } else if (res == G_ERROR_UNAUTHORIZED) {
                j_return = json_pack("{si}", "result", G_ERROR_UNAUTHORIZED);
              } else if (res != G_ERROR_NOT_FOUND) {
                y_log_message(Y_LOG_LEVEL_ERROR, "auth_check_user_credentials - Error, user_module_check_password for module '%s', skip", user_module->name);
              }
            } else if (!check_result_value(j_user, G_ERROR_NOT_FOUND)) {
              y_log_message(Y_LOG_LEVEL_ERROR, "auth_check_user_credentials - Error, user_module_get for module '%s', skip", user_module->name);
            }
            json_decref(j_user);
          }
        } else {
          y_log_message(Y_LOG_LEVEL_ERROR, "auth_check_user_credentials - Error, user_module_instance %s is NULL", json_string_value(json_object_get(j_module, "name")));
        }
      }
    }
  } else {
    y_log_message(Y_LOG_LEVEL_ERROR, "auth_check_user_credentials - Error get_user_module_list");
    j_return = json_pack("{si}", "result", G_ERROR);
  }
  if (j_return == NULL) {
    j_return = json_pack("{si}", "result", G_ERROR_UNAUTHORIZED);
  }
  json_decref(j_module_list);
  return j_return;
}

int glewlwyd_metrics_increment_counter(struct config_elements * config, const char * name, const char * label, size_t inc) { /* <=== glewlwyd_metrics_increment_counter */ 
  struct _glwd_increment_counter_data * data;
  pthread_t thread_metrics;
  int thread_ret, thread_detach;
  pthread_attr_t attr;
  struct sched_param param;
  int ret;

  if (config->metrics_endpoint) {
    if (config != NULL && o_strlen(name)) {
      if ((data = o_malloc(sizeof(struct _glwd_increment_counter_data))) != NULL) {
        data->config = config;
        data->name = o_strdup(name);
        data->label = o_strdup(label);
        data->inc = inc;
        pthread_attr_init (&attr);
        pthread_attr_getschedparam (&attr, &param);
        param.sched_priority = 0;
        pthread_attr_setschedparam (&attr, &param);
        thread_ret = pthread_create(&thread_metrics, &attr, glewlwyd_metrics_increment_counter_thread, (void *)data);
        thread_detach = pthread_detach(thread_metrics);
        if (thread_ret || thread_detach) {
          y_log_message(Y_LOG_LEVEL_ERROR, "glewlwyd_metrics_increment_counter - Error thread");
          o_free(data->name);
          o_free(data->label);
          o_free(data);
          ret = G_ERROR;
        } else {
          ret = G_OK;
        }
      } else {
        y_log_message(Y_LOG_LEVEL_ERROR, "glewlwyd_metrics_increment_counter - Error allocating resources for struct _glwd_increment_counter_data");
        ret = G_ERROR_MEMORY;
      }
    } else {
      y_log_message(Y_LOG_LEVEL_ERROR, "glewlwyd_metrics_increment_counter - Error input values");
      ret = G_ERROR_PARAM;
    }
  } else {
    ret = G_OK;
  }
  return ret;
}

int generate_digest(digest_algorithm digest, const char * data, int use_salt, char * out_digest) { /* <=== generate_digest */ 
  unsigned int res = 0;
  int alg, dig_res;
  gnutls_datum_t key_data;
  char * intermediate = NULL, salt[GLEWLWYD_DEFAULT_SALT_LENGTH + 1] = {0};
  unsigned char encoded_key[128 + GLEWLWYD_DEFAULT_SALT_LENGTH + 1] = {0};
  size_t encoded_key_size = (128 + GLEWLWYD_DEFAULT_SALT_LENGTH), encoded_key_size_base64;

  if (data != NULL && out_digest != NULL) {
    switch (digest) {
      case digest_SHA1:
        alg = GNUTLS_DIG_SHA1;
        break;
      case digest_SHA224:
        alg = GNUTLS_DIG_SHA224;
        break;
      case digest_SHA256:
        alg = GNUTLS_DIG_SHA256;
        break;
      case digest_SHA384:
        alg = GNUTLS_DIG_SHA384;
        break;
      case digest_SHA512:
        alg = GNUTLS_DIG_SHA512;
        break;
      case digest_MD5:
        alg = GNUTLS_DIG_MD5;
        break;
      default:
        alg = GNUTLS_DIG_UNKNOWN;
        break;
    }

    if(alg != GNUTLS_DIG_UNKNOWN) {
      if (o_strlen(data) > 0) {
        if (use_salt) {
          rand_string_nonce(salt, GLEWLWYD_DEFAULT_SALT_LENGTH);
          intermediate = msprintf("%s%s", data, salt);
        } else {
          intermediate = o_strdup(data);
        }
        key_data.data = (unsigned char*)intermediate;
        key_data.size = o_strlen(intermediate);
        if (key_data.data != NULL && (dig_res = gnutls_fingerprint(alg, &key_data, encoded_key, &encoded_key_size)) == GNUTLS_E_SUCCESS) {
          if (use_salt) {
            memcpy(encoded_key+encoded_key_size, salt, GLEWLWYD_DEFAULT_SALT_LENGTH);
            encoded_key_size += GLEWLWYD_DEFAULT_SALT_LENGTH;
          }
          if (o_base64_encode(encoded_key, encoded_key_size, (unsigned char *)out_digest, &encoded_key_size_base64)) {
            res = 1;
          } else{
            res = 0;
          }
        } else {
          res = 0;
        }
        o_free(intermediate);
      } else {
        // No data, then out_digest becomes an empty string
        out_digest[0] = '\0';
        res = 1;
      }
    } else {
      res = 0;
    }
  } else {
    res = 0;
  }
  return res;
}

const char * get_ip_source(const struct _u_request * request) { /* <=== get_ip_source */ 
  const char * ip_source = u_map_get_case(request->map_header, "X-Forwarded-For");

  if (ip_source == NULL) {
    struct sockaddr_in * in_source = (struct sockaddr_in *)request->client_address;
    if (in_source != NULL) {
      ip_source = inet_ntoa(in_source->sin_addr);
    } else {
      ip_source = "NOT_FOUND";
    }
  }

  return ip_source;
};

char * get_session_id(struct config_elements * config, const struct _u_request * request) { /* <=== get_session_id */ 
  if (o_strlen(u_map_get(request->map_cookie, config->session_key)) == GLEWLWYD_SESSION_ID_LENGTH) {
    return o_strdup(u_map_get(request->map_cookie, config->session_key));
  } else {
    return NULL;
  }
}

int generate_digest_crypt(const char * data, const char * method, char * out_digest) { /* <=== generate_digest_crypt */ 
  char salt[GLEWLWYD_DEFAULT_SALT_LENGTH+4] = {0},  * out_crypt;
  int res;

  if (method != NULL) {
    o_strcpy(salt, method);
  }
  rand_string_nonce(salt+o_strlen(method), GLEWLWYD_DEFAULT_SALT_LENGTH);
  if ((out_crypt = crypt(data, salt)) != NULL) {
    o_strcpy(out_digest, out_crypt);
    res = 1;
  } else {
    res = 0;
  }
  return res;
}

int user_session_update(struct config_elements * config, const char * session_uid, const char * user_agent, const char * issued_for, const char * username, const char * scheme_name, int update_login) { /* <=== user_session_update */ 
  json_t * j_query, * j_session = get_session_for_username(config, session_uid, username);
  struct _user_auth_scheme_module_instance * scheme_instance = NULL;
  int res, ret;
  time_t now;
  char * expiration_clause, * last_login_clause;
  char * session_uid_hash = generate_hash(config->hash_algorithm, session_uid);

  time(&now);
  if (session_uid_hash != NULL) {
    if (check_result_value(j_session, G_ERROR_NOT_FOUND)) {
      j_query = json_pack("{sss{si}s{ss}}",
                          "table",
                          GLEWLWYD_TABLE_USER_SESSION,
                          "set",
                            "gus_current",
                            0,
                          "where",
                            "gus_session_hash",
                            session_uid_hash);
      res = h_update(config->conn, j_query, NULL);
      json_decref(j_query);
      if (res == H_OK) {
        // Create session for user if not exist
        j_query = json_pack("{sss{sssssssssi}}",
                            "table",
                            GLEWLWYD_TABLE_USER_SESSION,
                            "values",
                              "gus_session_hash",
                              session_uid_hash,
                              "gus_username",
                              username,
                              "gus_user_agent",
                              user_agent!=NULL?user_agent:"",
                              "gus_issued_for",
                              issued_for!=NULL?issued_for:"",
                              "gus_current",
                              1);
        if (update_login) {
          if (config->conn->type==HOEL_DB_TYPE_MARIADB) {
            expiration_clause = msprintf("FROM_UNIXTIME(%u)", (now + config->session_expiration));
          } else if (config->conn->type==HOEL_DB_TYPE_PGSQL) {
            expiration_clause = msprintf("TO_TIMESTAMP(%u)", (now + config->session_expiration));
          } else { // HOEL_DB_TYPE_SQLITE
            expiration_clause = msprintf("%u", (now + config->session_expiration));
          }
          if (config->conn->type==HOEL_DB_TYPE_MARIADB) {
            last_login_clause = msprintf("FROM_UNIXTIME(%u)", (now));
          } else if (config->conn->type==HOEL_DB_TYPE_PGSQL) {
            last_login_clause = msprintf("TO_TIMESTAMP(%u)", (now));
          } else { // HOEL_DB_TYPE_SQLITE
            last_login_clause = msprintf("%u", (now));
          }
          json_object_set_new(json_object_get(j_query, "values"), "gus_last_login", json_pack("{ss}", "raw", last_login_clause));
          json_object_set_new(json_object_get(j_query, "values"), "gus_expiration", json_pack("{ss}", "raw", expiration_clause));
          o_free(last_login_clause);
          o_free(expiration_clause);
        }
        res = h_insert(config->conn, j_query, NULL);
        json_decref(j_query);
        json_decref(j_session);
        if (res == H_OK) {
